<script setup>import {computed} from 'vue';import {useRoute,RouterLink} from 'vue-router';import PageHero from '../components/PageHero.vue';import {services} from '../data/services';const item=computed(()=>services.find(s=>s.slug===useRoute().params.slug)||services[0])</script><template><PageHero eyebrow="SERVICE DETAIL" :title="item.title" :description="item.desc"/><section class="container detail split-page"><div class="image-placeholder detail-image"><span>IMAGECOPY<br>{{item.title}}</span></div><div><p class="eyebrow">SERVICE INFORMATION</p><h2>{{item.title}}</h2><p>{{item.details}}</p><h3>送印前提醒</h3><ul class="check-list"><li>確認尺寸、數量與單／雙面需求</li><li>檔案請依完稿須知整理</li><li>特殊紙材或加工請先洽詢</li></ul><RouterLink to="/pricing" class="btn">查看印刷價格</RouterLink></div></section></template>
